        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var finalOSS = ds.oss || 0;
            var finalPAR = ds.par30 || 0;
            var finalBorrowers = ds.activeBorrowers || 0;
            var finalWomenPct = ds.womenPct || 0;
            var finalDepth = ds.depth || 0;
            var invConf = ds.investorConfidence || 0;
            var donConf = ds.donorConfidence || 0;
            var regConf = ds.regulatorConfidence || 0;

            var socialScores = ds.socialScoreHistory || [];
            var financialScores = ds.financialScoreHistory || [];
            var avgSocial = socialScores.length > 0 ? Math.round(socialScores.reduce(function(s, v) { return s + v; }, 0) / socialScores.length) : 0;
            var avgFinancial = financialScores.length > 0 ? Math.round(financialScores.reduce(function(s, v) { return s + v; }, 0) / financialScores.length) : 0;

            var compositeScore = Math.round(avgFinancial * 0.4 + avgSocial * 0.4 + (invConf + donConf + regConf) / 3 * 0.2);

            var performance = 'Needs Improvement';
            if (compositeScore > 70 && finalOSS > 110) performance = 'Excellent';
            else if (compositeScore > 55) performance = 'Good';
            else if (compositeScore > 40) performance = 'Adequate';

            var insights = [];
            if (finalOSS > 120) insights.push('Strong financial sustainability achieved.');
            if (finalOSS < 100) insights.push('The institution is not yet self-sufficient. Donor dependence remains.');
            if (finalPAR < 5) insights.push('Portfolio quality is well managed.');
            if (finalPAR > 8) insights.push('Portfolio risk is dangerously high. Collections strategy needs review.');
            if (finalWomenPct > 70) insights.push('Gender focus is outstanding. Strong social mission alignment.');
            if (finalWomenPct < 50) insights.push('Women borrower share has declined. Possible mission drift.');
            if (finalDepth < 15) insights.push('Deep outreach maintained. Serving the truly underserved.');
            if (finalDepth > 40) insights.push('Outreach depth has become shallow. Average loan size is high relative to GNI.');

            return {
                compositeScore: compositeScore,
                avgSocialScore: avgSocial,
                avgFinancialScore: avgFinancial,
                finalOSS: finalOSS,
                finalPAR: finalPAR,
                finalBorrowers: finalBorrowers,
                finalWomenPct: finalWomenPct,
                stakeholderAvg: Math.round((invConf + donConf + regConf) / 3),
                performance: performance,
                insights: insights
            };
        }

